const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visitorPosition=null;let requests=[];let saved=[];let activeType='';let selected=null;let hostMode=false;let visibleLimit=24;let onlySaved=false;let galleryIndex=0;
const categories=['Accommodation','Retreats','Conferences & events','Pilgrimage','Schools & universities','Hospitals & clinics','Training centres','Seminaries & formation'];
const icons=['⌂','✧','◇','✝','▤','✚','◈','♧'];
function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function propertyAction(p){
 const c=p.category;
 if(c==='Schools & universities')return {card:'Explore school & admissions',title:'Learning starts here.',body:'Explore academic programmes, admissions and campus information through the school’s own channels.',official:'View admissions & programmes',section:'Programmes & admissions'};
 if(c==='Hospitals & clinics')return {card:'View healthcare services',title:'Find care and services.',body:'Check clinical services, appointment contacts and visiting arrangements directly with the healthcare provider.',official:'View healthcare information',section:'Healthcare & visits'};
 if(c==='Pilgrimage')return {card:'Plan a pilgrimage visit',title:'Plan a moment of prayer.',body:'Find pilgrimage information, worship schedules and visitor guidance from the church or shrine.',official:'View worship & visitor information',section:'Worship & pilgrimage'};
 if(c==='Seminaries & formation')return {card:'Explore formation & vocations',title:'Discover a vocation.',body:'Learn about formation, vocations and institutional visiting arrangements.',official:'View formation information',section:'Formation & vocations'};
 if(c==='Training centres')return {card:'Explore courses & training',title:'Build your next skill.',body:'Explore training courses, entry requirements and enrolment through the institution.',official:'View courses & enrolment',section:'Courses & training'};
 if(c==='Retreats')return {card:'Explore retreats',title:'Make time for reflection.',body:'Explore retreat options and ask the operator about dates and accommodation.',official:'View retreat information',section:'Retreats & spaces'};
 return {card:'Explore rooms & venues',title:'Make room for your plans.',body:'Choose a room or gathering space, add your dates and prepare a clear enquiry.',official:'Visit the official website',section:'Rooms & spaces'};
}
function areaDistance(p){if(!visitorPosition||!p.areaCoordinates)return Infinity;const rad=x=>x*Math.PI/180;const [a,b]=p.areaCoordinates;const [c,d]=visitorPosition;const h=Math.sin(rad(a-c)/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(rad(b-d)/2)**2;return 6371*2*Math.asin(Math.min(1,Math.sqrt(h)))}
function photoHTML(p){return p.image?`<img src="${p.image}" alt="${esc(p.name)} — photograph from the cited property or institutional source" loading="lazy">`:`<div class="photo-pending"><span>${icons[categories.indexOf(p.category)]||'⌂'}</span><small>Property photo pending</small></div>`}
function setupCatalogue(){ $('#location').innerHTML='<option value="">Anywhere in Rwanda</option>'+[...new Set(properties.map(p=>p.location))].filter(l=>l!=='Location to confirm').sort().map(l=>`<option>${l}</option>`).join('');$('#purpose').innerHTML='<option value="">All categories</option>'+categories.map(t=>`<option>${t}</option>`).join('');$('#chips').innerHTML=`<button class="chip active" data-type="">All places <small>${properties.length}</small></button>`+categories.map((t,i)=>`<button class="chip" data-type="${t}">${icons[i]} ${t} <small>${properties.filter(p=>p.types.includes(t)).length}</small></button>`).join('');$('#catalogueStats').textContent=`${properties.length} source-listed places · ${properties.filter(p=>p.image).length} with property photography · 5 provinces`; }

try{requests=JSON.parse(localStorage.getItem('sanctuary-requests')||'[]');saved=JSON.parse(localStorage.getItem('sanctuary-saved')||'[]');if(!Array.isArray(requests))requests=[];if(!Array.isArray(saved))saved=[];}catch{requests=[];saved=[]}
const today=new Date();const dateLocal=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const minDate=dateLocal(today);$('#checkin').min=minDate;
function persist(){try{localStorage.setItem('sanctuary-requests',JSON.stringify(requests));localStorage.setItem('sanctuary-saved',JSON.stringify(saved))}catch{toast('Storage unavailable. Records will last for this visit only.')}$('#bookingCount').textContent=requests.length}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function show(dialog){if(!dialog.open)dialog.showModal()}
function render(){const location=$('#location').value;const q=normalize($('#keyword').value.trim());const province=$('#province').value;const photoOnly=$('#photoOnly').checked;const selectedDiocese=$('#propertyDiocese').value;const selectedParish=$('#propertyParish').value;let filtered=properties.filter(p=>(!location||p.location===location||(location==='Kigali'&&p.province==='Kigali'))&&(!activeType||p.types.includes(activeType))&&(!province||p.province===province)&&(!photoOnly||p.image)&&(!selectedDiocese||p.diocese===selectedDiocese)&&(!selectedParish||(p.parishAreas||[]).some(a=>a.id===selectedParish))&&(!onlySaved||saved.includes(p.id))&&(!q||normalize([p.name,p.area,p.affiliation,...p.types].join(' ')).includes(q)));const sort=$('#sort').value;filtered.sort((a,b)=>sort==='nearby'?areaDistance(a)-areaDistance(b):sort==='name'?a.name.localeCompare(b.name):sort==='location'?a.location.localeCompare(b.location):(Number(Boolean(b.image))-Number(Boolean(a.image))));$('#localityNote').classList.toggle('hidden',!selectedParish);$('#results').textContent=`${filtered.length} places found`;$('#empty').classList.toggle('hidden',filtered.length>0);const shown=filtered.slice(0,visibleLimit);$('#propertyGrid').innerHTML=shown.map(p=>`<article class="property-card"><div class="card-photo"><a href="#property/${p.id}" aria-label="Explore ${esc(p.name)}">${photoHTML(p)}</a><span class="card-badge">${esc(p.category)}</span><button class="save ${saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button>${p.image?'<span class="image-note">Property photo · source in profile</span>':''}</div><div class="card-body"><span class="card-location">⌖ ${esc(p.area)}${visitorPosition&&Number.isFinite(areaDistance(p))?` · ~${Math.round(areaDistance(p))} km to district centre`:""}</span><h3><a href="#property/${p.id}">${esc(p.name)}</a></h3><p>${esc(p.description)}</p><div class="amenities">${p.types.slice(0,3).map(f=>`<span>${esc(f)}</span>`).join('')}</div><div class="card-bottom"><small>${p.directOnly?'Book directly with operator':p.bookingDemo?'Prepare a visit enquiry':propertyAction(p).section}</small><button data-view="${p.id}">${propertyAction(p).card} ↗</button></div></div></article>`).join('');$('#loadMore').classList.toggle('hidden',shown.length>=filtered.length);$('#loadMore').textContent=`Show more places (${Math.max(0,filtered.length-shown.length)} remaining)`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>locationHash(b.dataset.view));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;saved=saved.includes(id)?saved.filter(s=>s!==id):[...saved,id];persist();render();toast(saved.includes(id)?'Place saved on this device':'Place removed from saved places')});document.querySelectorAll('.chip').forEach(c=>{c.classList.toggle('active',c.dataset.type===activeType);c.setAttribute('aria-pressed',String(c.dataset.type===activeType))});$('#savedFilter').classList.toggle('active',onlySaved)}
function locationHash(id){window.location.hash=`property/${id}`}
function propertyContacts(p){const d=p.bookingDetails||{};return {email:(d.emails||[])[0]||'',phone:(d.phones||[])[0]||p.phone||'',website:d.officialWebsite||p.website||p.source,address:d.address||p.area}}
function roomSpaceCards(p){if(!p.types.some(t=>['Accommodation','Retreats','Conferences & events'].includes(t)))return `<h3>${propertyAction(p).section}</h3><p>${propertyAction(p).body}</p>`;const d=p.bookingDetails||{};const roomCards=(d.roomTypes||[]).map((r,i)=>`<article class="offering-card"><span class="offering-icon">⌂</span><h4>${esc(r.name)}</h4>${r.details?`<p>${esc(r.details)}</p>`:''}<span class="offering-note">Rate and availability from the operator</span>${p.directOnly?`<a class="underlined" href="${propertyContacts(p).website}" target="_blank" rel="noopener noreferrer">Ask the operator ↗</a>`:`<button class="text-btn" data-enquire-room="${i}">Enquire about this room ↗</button>`}</article>`).join('');const venues=(d.venueOptions||[]).map((v,i)=>`<article class="offering-card"><span class="offering-icon">◇</span><h4>${esc(v.name)}</h4>${v.capacity?`<p><strong>Operator’s published scale:</strong> ${esc(v.capacity)}</p>`:''}${v.details?`<p>${esc(v.details)}</p>`:''}<span class="offering-note">Confirm layout, capacity and equipment</span>${p.directOnly?`<a class="underlined" href="${propertyContacts(p).website}" target="_blank" rel="noopener noreferrer">Ask the operator ↗</a>`:`<button class="text-btn" data-enquire-venue="${i}">Plan an event here ↗</button>`}</article>`).join('');return `${roomCards?`<h3>Rooms & accommodation</h3><div class="offerings-grid">${roomCards}</div>`:''}${venues?`<h3>Meeting & gathering spaces</h3><div class="offerings-grid">${venues}</div>`:''}${roomCards||venues?'<p class="published-note">These are operator-published enquiry options, not a live inventory. No room, date or price is guaranteed.</p>':'<p>Room types, current services and venue configurations are still to be confirmed with the institution.</p>'}`}
function detail(id){const p=properties.find(p=>p.id===id);if(!p)return;selected=p;galleryIndex=0;const contacts=propertyContacts(p);const d=p.bookingDetails||{};$('#detailContent').innerHTML=`<div class="property-page-top"><span>THE SANCTUARY COLLECTION</span><span>${esc(p.province)} · Rwanda</span></div><div class="detail-image ${p.image?'':'no-photo'}" id="galleryHero">${p.image?`<img id="galleryMain" src="${p.image}" alt="${esc(p.name)} — photograph from the cited property source">`:'<div class="photo-pending"><span>⌂</span><small>Property photograph not yet sourced</small></div>'}</div>${p.gallery.length>1?`<div class="gallery-thumbs">${p.gallery.map((g,i)=>`<button data-gallery="${i}" class="${i===0?'selected':''}" aria-label="View photo ${i+1} of ${esc(p.name)}"><img src="${g.file}" alt="Property photo ${i+1}"></button>`).join('')}</div>`:''}<div class="detail-inner"><div class="eyebrow">${esc(p.area)}</div><h2>${esc(p.name)}</h2><div class="detail-tags">${p.types.map(t=>`<span class="status">${esc(t)}</span>`).join('')}${p.directOnly?'<span class="status direct-badge">Direct operator bookings</span>':''}</div><div class="property-page-tabs" aria-label="Property sections"><button data-section="propertyOverview">Overview</button><button data-section="propertySpaces">${p.types.some(t=>['Accommodation','Retreats','Conferences & events'].includes(t))?'Rooms & spaces':propertyAction(p).section}</button><button data-section="propertyLocation">Location & contact</button><button data-section="propertySources">Sources</button></div><div class="detail-columns"><div class="property-main"><section id="propertyOverview"><h3>${propertyAction(p).title}</h3><p>${esc(p.description)}</p><p><strong>Institutional connection</strong><br>${esc(p.affiliation)}</p>${p.directOnly?'<div class="operator-notice"><strong>Book directly with Centre Saint Paul.</strong><p>The operator states it does not currently use third-party booking platforms. Contact its own reservations team for room availability and confirmation.</p></div>':''}</section><section id="propertySpaces">${roomSpaceCards(p)}</section><section id="propertyLocation"><h3>Location & contact</h3><p>${esc(contacts.address)}</p><div class="contact-links"><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+contacts.address)}" target="_blank" rel="noopener noreferrer">Find the property on Maps ↗</a>${contacts.phone?`<a href="tel:${contacts.phone.replace(/[^+0-9]/g,'')}">Call ${esc(contacts.phone)}</a>`:''}${contacts.email?`<a href="mailto:${contacts.email}">${esc(contacts.email)}</a>`:''}<a href="${contacts.website}" target="_blank" rel="noopener noreferrer">Official property information ↗</a></div><p class="published-note">Confirm arrival directions, accessibility and current services before travelling.</p></section><section id="propertySources"><h3>Information you can check.</h3><p>${esc(p.verification)}</p><a class="source" href="${p.source}" target="_blank" rel="noopener noreferrer">View institutional / listing source ↗</a>${(d.sources||[]).filter(s=>s!==p.source).map((s,i)=>`<a class="source additional-source" href="${s}" target="_blank" rel="noopener noreferrer">Operator reference ${i+1} ↗</a>`).join('')}<p class="published-note">Sources reviewed 23 October 2026. This independent catalogue does not imply a booking partnership or prove legal ownership.</p>${d.notes?.some(n=>n.includes('2025'))?'<p class="published-note">Some published room configurations come from an operator brochure with an older accommodation section. Confirm the current setup directly.</p>':''}${p.gallery.length?`<p class="photo-attribution">Photo source: <a id="photoSource" href="${p.gallery[0].source}" target="_blank" rel="noopener noreferrer">original property / institutional publication ↗</a>. ${p.gallery[0].credit?esc(p.gallery[0].credit)+'. ':''}Image rights remain with the original rights holder.</p>`:'<p class="photo-attribution">A verified property photo is still pending; no stock image has been substituted.</p>'}</section></div><aside class="booking-box"><div class="eyebrow">${p.directOnly?'DIRECT RESERVATIONS':p.bookingDemo?'PLAN YOUR VISIT':'INSTITUTIONAL DIRECTORY'}</div><h3>${p.directOnly?'A personal welcome starts here.':p.bookingDemo?'Make room for your plans.':propertyAction(p).title}</h3><p>${p.directOnly?'Use the operator’s own contact channels to request dates, rates and confirmation.':p.bookingDemo?'Choose a room or gathering space, add your dates and prepare a clear enquiry.':propertyAction(p).body}</p>${p.bookingDemo?'<button class="primary" id="startBooking">Plan a stay or event ↗</button>':''}${p.directOnly&&contacts.email?`<a class="primary direct-link" href="mailto:${contacts.email}">Email reservations ↗</a>`:''}<a class="official-button" href="${contacts.website}" target="_blank" rel="noopener noreferrer">${p.directOnly?'Book with the operator':propertyAction(p).official} ↗</a>${contacts.phone?`<a class="official-button" href="tel:${contacts.phone.replace(/[^+0-9]/g,'')}">Call the property</a>`:''}<p class="booking-footnote">${p.bookingDemo?'Local planning demo. No payment, live availability or automatic delivery.':p.directOnly?'Confirmation comes from Centre Saint Paul’s own team.':'Directory only. Contact the institution directly.'}</p></aside></div></div>`;if($('#startBooking'))$('#startBooking').onclick=()=>booking(p);document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{galleryIndex=Number(b.dataset.gallery);$('#galleryMain').src=p.gallery[galleryIndex].file;$('#photoSource').href=p.gallery[galleryIndex].source;document.querySelectorAll('[data-gallery]').forEach(t=>t.classList.toggle('selected',t===b))});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>$('#'+b.dataset.section).scrollIntoView({behavior:'smooth',block:'start'}));document.querySelectorAll('[data-enquire-room]').forEach(b=>b.onclick=()=>booking(p,{kind:'Stay',room:d.roomTypes[Number(b.dataset.enquireRoom)].name}));document.querySelectorAll('[data-enquire-venue]').forEach(b=>b.onclick=()=>booking(p,{kind:'Meeting / event',venue:d.venueOptions[Number(b.dataset.enquireVenue)].name}));show($('#detailDialog'))}
function nightsBetween(a,b){return Math.max(0,Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000))}
function requestText(r,p){return `SANCTUARY RWANDA — ENQUIRY DRAFT\nThis is an enquiry, not a booking confirmation.\n\nProperty: ${p.name}\nPurpose: ${r.kind}\nArrival/start: ${r.arrival}\nDeparture/end: ${r.departure}\nGuests / participants: ${r.guests}\nRooms requested: ${r.rooms}\nRoom preference: ${r.roomType||'Please advise'}\nVenue preference: ${r.venue||'Please advise'}\nFlexible dates: ${r.flexible?'Yes':'No'}\n\nName: ${r.name}\nEmail: ${r.email}\nPhone: ${r.phone||'Not supplied'}\nAdditional requests: ${r.notes||'None'}\n\nPlease confirm suitability, availability, the full price, cancellation terms and any deposit requirements directly.\nReference: ${r.id||'Draft'}\n`}
function booking(p,prefill={}){if(!p.bookingDemo||p.directOnly)return;$('#detailDialog').close();const d=p.bookingDetails||{};const contact=propertyContacts(p);const date=$('#checkin').value||minDate;const following=new Date(date+'T12:00:00');following.setDate(following.getDate()+1);let step=1;const kinds=['Stay',...(p.types.includes('Retreats')?['Overnight retreat','Day retreat']:[]),...(p.types.includes('Conferences & events')?['Meeting / event']:[])];if(prefill.kind&&!kinds.includes(prefill.kind))kinds.push(prefill.kind);const opts=(rows)=>'<option value="">Let the property advise</option>'+(rows||[]).map(r=>`<option>${esc(r.name)}</option>`).join('');$('#bookingContent').innerHTML=`<div class="wizard-header"><div class="eyebrow">PLAN A MEANINGFUL VISIT</div><h2>${esc(p.name)}</h2><p>A thoughtful enquiry. A personal response from the property.</p></div><ol class="wizard-progress"><li data-progress="1">1 <span>Your visit</span></li><li data-progress="2">2 <span>Your details</span></li><li data-progress="3">3 <span>Review</span></li></ol><form id="reservationForm" novalidate><section class="wizard-step" data-step="1"><h3>What brings you here?</h3><div class="form-grid"><label class="full">Visit type<select name="kind" required>${kinds.map(k=>`<option>${k}</option>`).join('')}</select></label><label><span id="arrivalLabel">Arrival</span><input name="arrival" type="date" min="${minDate}" value="${date}" required></label><label><span id="departureLabel">Departure</span><input name="departure" type="date" min="${dateLocal(following)}" value="${dateLocal(following)}" required></label><label>Guests / participants<input name="guests" type="number" min="1" max="1500" value="${$('#guests').value}" required></label><label><span id="roomsLabel">Rooms requested</span><input name="rooms" type="number" min="1" max="500" value="1" required></label>${d.roomTypes?.length?`<label class="full">Room preference<select name="roomType">${opts(d.roomTypes)}</select></label>`:''}${d.venueOptions?.length?`<label class="full">Meeting / gathering space (optional)<select name="venue">${opts(d.venueOptions)}</select></label>`:''}<label class="full consent"><input name="flexible" type="checkbox"><span>My dates are flexible.</span></label></div><p class="published-note">Options come from the property’s published information. Choosing an option does not reserve it or establish a price.</p></section><section class="wizard-step hidden" data-step="2"><h3>Who is planning the visit?</h3><div class="demo-notice">Use sample details while exploring this prototype. Your draft stays in this browser; it is not sent automatically to the property.</div><div class="form-grid"><label>Your name<input name="name" autocomplete="name" placeholder="Demo Visitor" maxlength="100" required></label><label>Email address<input name="email" type="email" autocomplete="email" placeholder="demo@example.com" maxlength="150" required></label><label class="full">Phone (optional)<input name="phone" type="tel" autocomplete="tel" maxlength="40" placeholder="Include country code"></label><label class="full">What would make your visit work?<textarea name="notes" rows="4" maxlength="1500" placeholder="Meeting setup, meals, arrival plans or general accessibility requests. Please leave out sensitive personal details."></textarea></label><label class="full consent"><input name="acknowledged" type="checkbox" required><span>I understand this saves a local demo draft, and that the property must confirm availability and terms directly.</span></label></div></section><section class="wizard-step hidden" data-step="3"><h3>A quick look before the next step.</h3><div id="requestReview"></div><div class="demo-notice">No payment is taken and no room is held. Saving this draft does not contact the operator. ${contact.email?'You can then choose to open an email draft in your own email app.':'Use the operator’s official website or phone to make your actual enquiry.'}</div></section><p id="wizardError" class="form-error" role="alert"></p><div class="wizard-actions"><button type="button" class="outline" id="wizardBack">← Back</button><span id="wizardStepLabel">Step 1 of 3</span><button class="primary" id="wizardNext" type="submit">Continue ↗</button></div></form>`;const form=$('#reservationForm');if(prefill.kind)form.elements.kind.value=prefill.kind;if(prefill.room&&form.elements.roomType)form.elements.roomType.value=prefill.room;if(prefill.venue&&form.elements.venue)form.elements.venue.value=prefill.venue;const data=()=>Object.fromEntries(new FormData(form));function applyKind(){const event=['Meeting / event','Day retreat'].includes(form.elements.kind.value);$('#arrivalLabel').textContent=event?'Start date':'Arrival';$('#departureLabel').textContent=event?'End date':'Departure';$('#roomsLabel').textContent=event?'Rooms requested (0 for a day event)':'Rooms requested';form.elements.rooms.min=event?'0':'1';if(event&&form.elements.rooms.value==='1')form.elements.rooms.value='0';if(!event&&Number(form.elements.rooms.value)<1)form.elements.rooms.value='1';const next=new Date(form.elements.arrival.value+'T12:00:00');if(!event)next.setDate(next.getDate()+1);form.elements.departure.min=dateLocal(next);if(form.elements.departure.value<form.elements.departure.min)form.elements.departure.value=form.elements.departure.min}
function validate(){const panel=form.querySelector(`[data-step="${step}"]`);form.elements.departure.setCustomValidity('');if(step===1){const v=data();const event=['Meeting / event','Day retreat'].includes(v.kind);if(v.departure<v.arrival||(!event&&v.departure===v.arrival))form.elements.departure.setCustomValidity(event?'End date must be on or after the start date.':'Departure must be after arrival.')}for(const input of panel.querySelectorAll('input,select,textarea'))if(!input.reportValidity())return false;return true}
function review(){const r=data();$('#requestReview').innerHTML=`<div class="review-property"><span class="status">Enquiry draft · not confirmed</span><h4>${esc(p.name)}</h4><p>${esc(r.kind)} · ${nightsBetween(r.arrival,r.departure)} ${nightsBetween(r.arrival,r.departure)===1?'night':'nights'}</p></div><dl class="request-summary"><div><dt>Dates</dt><dd>${esc(r.arrival)} → ${esc(r.departure)}</dd></div><div><dt>Party</dt><dd>${esc(r.guests)} guests / participants</dd></div><div><dt>Rooms</dt><dd>${esc(r.rooms)} requested</dd></div>${r.roomType?`<div><dt>Room preference</dt><dd>${esc(r.roomType)}</dd></div>`:''}${r.venue?`<div><dt>Venue preference</dt><dd>${esc(r.venue)}</dd></div>`:''}<div><dt>Dates flexible</dt><dd>${r.flexible?'Yes':'No'}</dd></div><div><dt>Planner</dt><dd>${esc(r.name)}<br>${esc(r.email)}${r.phone?'<br>'+esc(r.phone):''}</dd></div>${r.notes?`<div><dt>Additional requests</dt><dd>${esc(r.notes)}</dd></div>`:''}<div><dt>Price & availability</dt><dd>To be confirmed by the property</dd></div></dl>`}
function update(){form.querySelectorAll('.wizard-step').forEach(s=>s.classList.toggle('hidden',Number(s.dataset.step)!==step));document.querySelectorAll('[data-progress]').forEach(el=>{el.classList.toggle('current',Number(el.dataset.progress)===step);el.classList.toggle('complete',Number(el.dataset.progress)<step);if(Number(el.dataset.progress)===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('#wizardBack').classList.toggle('hidden',step===1);$('#wizardStepLabel').textContent=`Step ${step} of 3`;$('#wizardNext').textContent=step===3?'Save demo draft ↗':'Continue ↗';if(step===3)review();$('#bookingDialog').scrollTop=0}
form.elements.kind.onchange=applyKind;form.elements.arrival.onchange=applyKind;$('#wizardBack').onclick=()=>{if(step>1){step--;update()}};form.onsubmit=e=>{e.preventDefault();if(!validate())return;if(step<3){step++;update();return}const r={...data(),id:'SR-'+crypto.randomUUID().slice(0,8).toUpperCase(),property:p.id,status:'Draft prepared',created:new Date().toISOString()};requests.unshift(r);persist();const emailHref=contact.email?`mailto:${contact.email}?subject=${encodeURIComponent('Stay / event enquiry — '+p.name+' — '+r.arrival)}&body=${encodeURIComponent(requestText(r,p))}`:'';$('#bookingContent').innerHTML=`<div class="success-mark">✓</div><div class="eyebrow">YOUR DEMO DRAFT IS READY</div><h2>A clear plan.<br>A personal next step.</h2><p>Reference <strong>${esc(r.id)}</strong> · ${esc(p.name)}</p><div class="request-item"><p>${esc(r.arrival)} → ${esc(r.departure)}<br>${esc(r.guests)} guests / participants · ${esc(r.rooms)} ${Number(r.rooms)===1?'room':'rooms'} requested${r.roomType?'<br>'+esc(r.roomType):''}${r.venue?'<br>'+esc(r.venue):''}</p><span class="status">Saved locally · not sent</span></div>${emailHref?`<a class="primary direct-link" id="operatorEmailDraft" href="${esc(emailHref)}">Open an email draft to the property ↗</a><p class="published-note">Opens your email app with these details. You review and send it there. Sanctuary does not send the email or confirm a booking.</p>`:`<a class="primary direct-link" href="${contact.website}" target="_blank" rel="noopener noreferrer">Continue with the operator ↗</a>`}<div class="completion-actions"><button class="outline" id="downloadPrepared">Download enquiry summary ↓</button><button class="text-btn" id="viewRequests">View my local requests ↗</button></div><div class="demo-notice">No email has been sent and no room is reserved. Availability, full pricing and booking terms must come from the property.</div>`;$('#downloadPrepared').onclick=()=>download(r);$('#viewRequests').onclick=()=>{$('#bookingDialog').close();openRequests(false)}};applyKind();update();show($('#bookingDialog'))}

function openRequests(host){hostMode=host;renderRequests();show($('#listDialog'))}
function renderRequests(){const active=requests.filter(r=>r.status!=='Cancelled');$('#listContent').innerHTML=`<div class="eyebrow">${hostMode?'PROPERTY OPERATIONS · DEMO':'YOUR TRAVEL PLANS'}</div><h2>${hostMode?'A little more organized.':'Your requests.'}</h2><div class="demo-notice">${hostMode?'This is a local workspace demonstration, not a secured staff portal. It shows only requests saved in this browser. Status changes do not notify properties or guests.':'Requests are saved only in this browser. They are demonstrations, not confirmed bookings. Use sample details.'}</div>${hostMode?`<div class="workspace-summary"><div><strong>${requests.length}</strong>Total requests</div><div><strong>${requests.filter(r=>r.status==='New request').length}</strong>Needs review</div><div><strong>${active.length}</strong>Active records</div></div><label style="font-size:12px">Filter by property <select id="hostFilter"><option value="">All properties</option>${properties.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label>`:''}<div id="requestRows"></div>${requests.length?'<button class="outline" id="clearRequests">Delete all local demo data</button>':''}`;renderRows();if(hostMode)$('#hostFilter').onchange=renderRows;if($('#clearRequests'))$('#clearRequests').onclick=()=>{info('Delete demo data?',`<p>This permanently removes every demo request stored by Sanctuary Rwanda in this browser.</p><button class="primary" id="confirmDelete">Delete local requests</button>`);$('#confirmDelete').onclick=()=>{requests=[];persist();$('#infoDialog').close();renderRequests();toast('Local demo requests deleted')}}}
function renderRows(){const filter=hostMode?$('#hostFilter').value:'';const rows=requests.filter(r=>!filter||r.property===filter);$('#requestRows').innerHTML=rows.length?rows.map(r=>{const p=properties.find(p=>p.id===r.property);return `<article class="request-item"><span class="eyebrow">${esc(r.id)}</span><h3>${p?p.name:'Property'}</h3><span class="status">${esc(r.status)} · local demo</span><p>${esc(r.kind)}${r.roomType?' · '+esc(r.roomType):''}${r.venue?' · '+esc(r.venue):''}<br>${esc(r.arrival)} → ${esc(r.departure)} · ${esc(r.guests)} guests<br>${esc(r.name)} · ${esc(r.email)}${r.notes?'<br>'+esc(r.notes):''}</p><div class="actions">${hostMode&&r.status!=='Cancelled'?`<button class="outline" data-status="${esc(r.id)}" data-next="Reviewed">Mark reviewed</button><button class="outline" data-status="${esc(r.id)}" data-next="Quote prepared">Mark quote prepared</button>`:''}${r.status!=='Cancelled'?`<button class="outline" data-status="${esc(r.id)}" data-next="Cancelled">Cancel demo request</button>`:''}<button class="text-btn" data-download="${esc(r.id)}">Download summary ↓</button></div></article>`}).join(''):'<div class="empty"><h3>No requests here yet.</h3><p>Explore a property and create a demo request to try the journey.</p><button class="primary" id="browsePlaces">Explore places ↗</button></div>';document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const r=requests.find(r=>r.id===b.dataset.status);if(r){r.status=b.dataset.next;persist();renderRequests();toast('Demo request updated')}});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download(requests.find(r=>r.id===b.dataset.download)));if($('#browsePlaces'))$('#browsePlaces').onclick=()=>{$('#listDialog').close();window.location.hash='collection'}}
function download(r){const p=properties.find(p=>p.id===r.property);if(!p)return;const url=URL.createObjectURL(new Blob([requestText(r,p)],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=`${r.id}-enquiry.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function info(title,body){$('#infoContent').innerHTML=`<h2>${title}</h2>${body}`;show($('#infoDialog'))}
setupCatalogue();$('#searchForm').onsubmit=e=>{e.preventDefault();activeType=$('#purpose').value;visibleLimit=24;render();$('#collection').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{activeType=b.dataset.type;$('#purpose').value=activeType;visibleLimit=24;render()});document.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>{activeType=({Retreat:'Retreats',Conference:'Conferences & events',Stay:'Accommodation'})[b.dataset.journey];$('#purpose').value=activeType;$('#location').value='';visibleLimit=24;render();$('#collection').scrollIntoView({behavior:'smooth'})});$('#reset').onclick=()=>{activeType='';$('#purpose').value='';$('#location').value='';$('#province').value='';$('#propertyDiocese').value='';$('#propertyParish').value='';$('#keyword').value='';$('#photoOnly').checked=false;onlySaved=false;visibleLimit=24;render()};$('#myBookings').onclick=()=>openRequests(false);$('#workspace').onclick=$('#hostDemo').onclick=()=>openRequests(true);$('#howWorks').onclick=()=>info('A simple way to plan.', '<p>Explore a property, choose a published room or venue option, add your dates and review a local enquiry draft. Where a verified reservations email is available, you can open a draft in your own email app and send it yourself.</p><p>Confirmation, prices and terms come from the operator. Centre Saint Paul requires direct bookings and is linked to its own channels. Live inventory, platform email delivery and payments are not connected.</p>');$('#privacy').onclick=()=>info('Your information, your device.', '<p>This prototype saves requests and saved places in your browser’s local storage. Anyone using this browser can access its demo workspace. Use sample details only.</p><p>Sanctuary does not automatically send a request or collect payment. If you choose to open an email draft, the information goes to your own email app; you review and send it there. Delete local drafts from My requests using “Delete all local demo data.” Clearing browser storage also removes them.</p><p>Property photographs are served from this prototype’s local assets, with their original institutional source linked in each profile. Image rights remain with their owners; reuse permissions require confirmation before a public commercial launch. Fonts load from Google Fonts. Listings without verified property photography use a text placeholder. This independent concept is not endorsed by the Catholic Church or the listed institutions.</p>');document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)d.close()}}));$('#detailDialog').addEventListener('close',()=>{if(location.hash.startsWith('#property/'))history.replaceState(null,'',location.pathname+location.search+'#collection')});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#property/'))detail(location.hash.split('/')[1])});persist();render();if(location.hash.startsWith('#property/'))detail(location.hash.split('/')[1]);

$('#keyword').oninput=()=>{visibleLimit=24;render()};$('#propertyParish').onchange=$('#propertyDiocese').onchange=$('#province').onchange=$('#sort').onchange=$('#photoOnly').onchange=()=>{visibleLimit=24;render()};$('#loadMore').onclick=()=>{visibleLimit+=24;render()};$('#savedFilter').onclick=()=>{onlySaved=!onlySaved;visibleLimit=24;render()};

let parishLimit=24;
const dioceses=['Butare','Byumba','Cyangugu','Gikongoro','Kabgayi','Kibungo','Kigali','Nyundo','Ruhengeri'];
function setupParishes(){
 $('#propertyParish').innerHTML='<option value="">All / unassigned</option>'+parishes.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${p.id}">${esc(p.name)} — ${p.diocese}</option>`).join('');
 $('#parishStats').textContent=`${parishes.length} parish / quasi-parish records · 9 dioceses · property and parish counts kept separate`;
 $('#parishDiocese').innerHTML='<option value="">All dioceses</option>'+dioceses.map(d=>`<option>${d}</option>`).join('');
 $('#dioceseGrid').innerHTML=dioceses.map(d=>`<button class="diocese-card" data-diocese="${d}"><span>${d==='Kigali'?'ARCHDIOCESE':'DIOCESE'}</span><h3>${d}</h3><small>${parishes.filter(p=>p.diocese===d).length} parish records</small><strong>↗</strong></button>`).join('');
 document.querySelectorAll('[data-diocese]').forEach(b=>b.onclick=()=>{$('#parishDiocese').value=b.dataset.diocese;$('#parishSelect').value='';$('#parishSearch').value='';parishLimit=24;updateParishSelect();renderParishes();$('#parishDiocese').focus()});
 updateParishSelect();renderParishes();
}
function updateParishSelect(){const d=$('#parishDiocese').value;$('#parishSelect').innerHTML='<option value="">All listed parishes</option>'+parishes.filter(p=>!d||p.diocese===d).sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${p.id}">${esc(p.name)}${d?'':' — '+p.diocese}</option>`).join('')}
function renderParishes(){const d=$('#parishDiocese').value;const id=$('#parishSelect').value;const q=normalize($('#parishSearch').value);const rows=parishes.filter(p=>(!d||p.diocese===d)&&(!id||p.id===id)&&(!q||normalize(p.name).includes(q))).sort((a,b)=>a.diocese.localeCompare(b.diocese)||a.name.localeCompare(b.name));$('#parishResults').textContent=`${rows.length} parish records`;$('#parishGrid').innerHTML=rows.slice(0,parishLimit).map(p=>`<article class="parish-card"><span class="parish-icon">✝</span><div><small>${esc(p.diocese)} ${p.diocese==='Kigali'?'Archdiocese':'Diocese'}</small><h3>${esc(p.name)}</h3><p>${esc(p.kind||'Parish record')}</p><button class="text-btn" data-parish="${p.id}">Explore parish ↗</button></div></article>`).join('')||'<p>No parish matches your selection. Try another name.</p>';$('#moreParishes').classList.toggle('hidden',rows.length<=parishLimit);document.querySelectorAll('[data-parish]').forEach(b=>b.onclick=()=>showParish(b.dataset.parish));document.querySelectorAll('[data-diocese]').forEach(b=>b.classList.toggle('selected',d===b.dataset.diocese))}
function showParish(id){const p=parishes.find(p=>p.id===id);if(!p)return;const count=properties.filter(x=>x.diocese===p.diocese).length;const localCount=properties.filter(x=>(x.parishAreas||[]).some(a=>a.id===p.id)).length;info(esc(p.name)+((p.kind||'').toLowerCase().includes('quasi')?' — Quasi-parish':' Parish'),`<div class="eyebrow">${esc(p.diocese)} ${p.diocese==='Kigali'?'ARCHDIOCESE':'DIOCESE'}</div><p>${esc(p.kind||'Parish listed in a diocesan or episcopal source.')}</p>${p.location?`<p><strong>Location:</strong> ${esc(p.location)}</p>`:''}<p><strong>Source information:</strong> ${esc(p.sourceDate||'Date not specified by source')}.</p>${p.verificationNote?`<p>${esc(p.verificationNote)}</p>`:''}<a class="official-button" target="_blank" rel="noopener noreferrer" href="${p.source}">View the parish source ↗</a><div class="demo-notice">Parish ownership and boundaries are not confirmed by a place-name match. ${localCount?`${localCount} collection places share this parish’s documented locality.`:'No locality matches are linked to this parish yet.'} Check current access and services with the operator.</div>${localCount?`<button class="primary" id="exploreParishLocality">Explore ${localCount} places in this locality ↗</button><p style="font-size:10px">Locality links help you browse; they do not establish parish ownership or booking availability.</p>`:''}<button class="primary" id="exploreDioceseProperties">Explore ${count} ${count===1?'property':'properties'} with a ${esc(p.diocese)} connection ↗</button><p style="font-size:10px">These are properties connected to the diocese; they are not confirmed as belonging to this parish.</p>`);$('#exploreDioceseProperties').onclick=()=>{$('#infoDialog').close();$('#propertyDiocese').value=p.diocese;$('#propertyParish').value='';$('#location').value='';$('#province').value='';$('#keyword').value='';$('#photoOnly').checked=false;onlySaved=false;activeType='';$('#purpose').value='';visibleLimit=24;render();$('#collection').scrollIntoView({behavior:'smooth'})};if($('#exploreParishLocality'))$('#exploreParishLocality').onclick=()=>{$('#infoDialog').close();$('#propertyDiocese').value='';$('#propertyParish').value=p.id;$('#location').value='';$('#province').value='';$('#keyword').value='';$('#photoOnly').checked=false;onlySaved=false;activeType='';$('#purpose').value='';visibleLimit=24;render();$('#collection').scrollIntoView({behavior:'smooth'})}}
$('#parishDiocese').onchange=()=>{parishLimit=24;updateParishSelect();renderParishes()};$('#parishSelect').onchange=$('#parishSearch').oninput=()=>{parishLimit=24;renderParishes()};$('#moreParishes').onclick=()=>{parishLimit+=36;renderParishes()};setupParishes();

$('#nearMe').onclick=()=>{if(!navigator.geolocation){$('#nearbyStatus').textContent='Location is unavailable. Choose a district above.';return}$('#nearbyStatus').textContent='Waiting for your location permission…';navigator.geolocation.getCurrentPosition(pos=>{visitorPosition=[pos.coords.latitude,pos.coords.longitude];$('#sort').value='nearby';$('#location').value='';$('#province').value='';visibleLimit=24;render();$('#nearbyStatus').textContent='Sorted by approximate distance to each district centre. Property entrance coordinates are not verified. Your location stays in memory on this device.'},()=>{$('#nearbyStatus').textContent='Location was not available. Choose a district above or allow location access in your browser.'},{enableHighAccuracy:false,timeout:12000,maximumAge:60000})};
$('#clearLocation').onclick=()=>{visitorPosition=null;$('#sort').value='photos';$('#nearbyStatus').textContent='Location cleared. You can also browse by district.';render()};
